function HomePage({ onYes }) {

    const [pos, setPos] = useState({ x: 0, y: 0 });
    const [moved, setMoved] = useState(false);

    const move = () => {
        const x = Math.random() * (window.innerWidth - 200);
        const y = Math.random() * (window.innerHeight - 100);

        setPos({ x, y });
        setMoved(true);
    };

    return (
        <div className="home-page">

            <h1 className="title">Will you be my Valentine? 💝</h1>

            {/* YES */}
            <button
                className="brutalist-button button-1 yes-brutal"
                onClick={onYes}
            >
                YES 💖
            </button>

            {/* NO */}
            <button
                className="brutalist-button button-1 no-brutal"
                onMouseEnter={move}
                onClick={move}
                onTouchStart={move}
                style={
                    moved
                        ? { left: pos.x, top: pos.y, position: "absolute" }
                        : { position: "relative" }
                }
            >
                NO 😜
            </button>

        </div>
    );
}

/* DINO GAME */

function DinoGamePage({ onFinish }) {

    const dinoRef = useRef(null);
    const gridRef = useRef(null);
    const alertRef = useRef(null);

    const [isGameOver, setIsGameOver] = useState(false);

    let gravity = 0.9;
    let isJumping = false;
    let position = 0;

    useEffect(() => {

        function control(e) {
            if (e.code === "Space") {
                if (!isJumping) {
                    jump();
                }
            }
        }

        document.addEventListener("keydown", control);

        function jump() {

            if (isGameOver) return;

            isJumping = true;
            let count = 0;

            let timerId = setInterval(() => {

                /* Going down */
                if (count === 15) {

                    clearInterval(timerId);

                    let downTimerId = setInterval(() => {

                        if (count === 0) {
                            clearInterval(downTimerId);
                            isJumping = false;
                        }

                        position -= 5;
                        count--;
                        position = position * gravity;

                        if (dinoRef.current) {
                            dinoRef.current.style.bottom = position + "px";
                        }

                    }, 20);
                }

                /* Going up */
                position += 30;
                count++;
                position = position * gravity;

                if (dinoRef.current) {
                    dinoRef.current.style.bottom = position + "px";
                }

            }, 20);
        }

        function generateObstacles() {

            if (isGameOver) return;

            let randomTime = Math.random() * 4000;
            let obstaclePosition = 600;

            const obstacle = document.createElement("div");
            obstacle.classList.add("obstacle");

            if (gridRef.current) {
                gridRef.current.appendChild(obstacle);
            }

            obstacle.style.left = obstaclePosition + "px";

            let timerId = setInterval(() => {

                if (
                    obstaclePosition > 0 &&
                    obstaclePosition < 60 &&
                    position < 60
                ) {
                    clearInterval(timerId);

                    if (alertRef.current) {
                        alertRef.current.innerHTML = "Game Over 😢";
                    }

                    setIsGameOver(true);

                    if (gridRef.current) {
                        gridRef.current.innerHTML = "";
                    }

                    return;
                }

                obstaclePosition -= 10;
                obstacle.style.left = obstaclePosition + "px";

            }, 20);

            setTimeout(generateObstacles, randomTime);
        }

        generateObstacles();

        return () => {
            document.removeEventListener("keydown", control);
        };

    }, [isGameOver]);

    return (
        <div className="game-page">

            <h2>🦖 Dino Love Run 💖</h2>

            <div ref={alertRef} id="alert"></div>

            <div ref={gridRef} className="grid">

                <div ref={dinoRef} className="dino">
                    🦕
                </div>

            </div>

            {isGameOver && (

                <div style={{ marginTop: 20 }}>

                    <button
                        className="submit-button"
                        onClick={onFinish}
                    >
                        Continue 💖
                    </button>

                </div>
            )}

            <p>Press SPACE to Jump</p>

        </div>
    );
}

